package com.lamggm.rospocket;
import android.view.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31) @LooperMode(LooperMode.Mode.PAUSED)
public class ImmersiveActivityTest {
 final ConnectionActivityTest f=new ConnectionActivityTest();@Before public void setup()throws Exception{if(android.os.Build.VERSION.SDK_INT<30)f.a=Robolectric.buildActivity(MainActivity.class).create().get();else f.setup();}@After public void cleanup()throws Exception{f.cleanup();}
 void assertFullscreen(){int flags=f.a.getWindow().getDecorView().getSystemUiVisibility();int required=View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION;assertEquals("Immersive requests both bars hidden with gesture recovery",required,flags&required);}
 @Test public void visibleKeyboardReservesAnImeSafeActivityViewport(){View root=f.a.getWindow().getDecorView().findViewWithTag("app-root");WindowInsets insets=new WindowInsets.Builder().setInsets(WindowInsets.Type.systemBars(),android.graphics.Insets.of(0,24,0,16)).setInsets(WindowInsets.Type.ime(),android.graphics.Insets.of(0,0,0,340)).setVisible(WindowInsets.Type.ime(),true).build();root.dispatchApplyWindowInsets(insets);assertEquals("Keyboard must not cover Activity-hosted fields",340,root.getPaddingBottom());assertEquals(24,root.getPaddingTop());WindowInsets hidden=new WindowInsets.Builder().setInsets(WindowInsets.Type.systemBars(),android.graphics.Insets.NONE).setInsets(WindowInsets.Type.ime(),android.graphics.Insets.NONE).setVisible(WindowInsets.Type.ime(),false).build();root.dispatchApplyWindowInsets(hidden);assertEquals(0,root.getPaddingBottom());assertEquals(0,root.getPaddingTop());}
 @Test public void startsImmersiveAndReentersAfterDialogFocusWithoutChangingReaders(){assertFullscreen();int starts=f.bridge.starts,subs=f.bridge.subscriptions;f.a.getWindow().getDecorView().setSystemUiVisibility(0);f.a.onWindowFocusChanged(true);assertFullscreen();f.a.applyAppearance();assertFullscreen();assertEquals(starts,f.bridge.starts);assertEquals(subs,f.bridge.subscriptions);}
 @Test @Config(sdk=28) public void oldAndroidAlsoRetainsGestureAccessibleFullscreen(){assertFullscreen();}
}
